import { expect, test } from "@playwright/test";
import fs from "node:fs";
import path from "node:path";

const API = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";
const FIXTURES = path.resolve(__dirname, "../../../samples/fictional");

function ensurePdfFixture(): string {
  const target = path.join(FIXTURES, "phase8-security-text.pdf");
  if (!fs.existsSync(target)) {
    // Minimal valid-looking PDF bytes are generated by backend helpers in CI/local Docker.
    // Fallback: reuse phase5 fixture if present.
    const fallback = path.join(FIXTURES, "phase5-text.pdf");
    if (fs.existsSync(fallback)) return fallback;
  }
  return target;
}

test.describe("Phase 8 security E2E", () => {
  test("malicious upload is safely rejected", async ({ page, request }) => {
    // PE MZ header disguised as PDF
    const pe = Buffer.from([0x4d, 0x5a, 0x90, 0x00, 0x03, 0x00, 0x00, 0x00]);
    const response = await request.post(`${API}/api/v1/documents`, {
      multipart: {
        file: {
          name: "evil.pdf",
          mimeType: "application/pdf",
          buffer: pe,
        },
      },
    });
    expect(response.status()).toBe(400);
    const body = await response.json();
    expect(body.error.code).toMatch(/EXECUTABLE|SIGNATURE|UNSUPPORTED|ARCHIVE/);
    expect(JSON.stringify(body).toLowerCase()).not.toContain("traceback");
    expect(JSON.stringify(body).toLowerCase()).not.toContain("c:\\");

    await page.goto("/");
    await expect(page.getByText(/Intelligent PII/i)).toBeVisible();
  });

  test("delete-now clears job access after processing", async ({ page, request }) => {
    const fixture = ensurePdfFixture();
    test.skip(!fs.existsSync(fixture), "PDF fixture unavailable");

    const upload = await request.post(`${API}/api/v1/documents`, {
      multipart: {
        file: {
          name: "phase8.pdf",
          mimeType: "application/pdf",
          buffer: fs.readFileSync(fixture),
        },
      },
    });
    expect(upload.status()).toBe(201);
    const job = await upload.json();
    const jobId = job.job_id as string;

    const del = await request.delete(`${API}/api/v1/jobs/${jobId}`);
    expect(del.status()).toBe(200);

    const after = await request.get(`${API}/api/v1/jobs/${jobId}`);
    expect(after.status()).toBe(404);

    const audit = await request.get(`${API}/api/v1/jobs/${jobId}/audit-report`);
    expect(audit.status()).toBe(404);

    await page.goto("/");
    expect(await page.evaluate(() => localStorage.length)).toBe(0);
    expect(await page.evaluate(() => sessionStorage.length)).toBe(0);
  });

  test("browser storage stays empty after fictional text flow", async ({ page }) => {
    await page.goto("/");
    const textarea = page
      .getByLabel(/paste text/i)
      .or(page.locator("textarea"))
      .first();
    if (await textarea.count()) {
      await textarea.fill("Contact casey.okafor@example.test at 902-555-0182");
    }
    expect(await page.evaluate(() => localStorage.length)).toBe(0);
    expect(await page.evaluate(() => sessionStorage.length)).toBe(0);
  });

  test("cross-job artifact access is rejected", async ({ request }) => {
    const fixture = ensurePdfFixture();
    test.skip(!fs.existsSync(fixture), "PDF fixture unavailable");
    const bytes = fs.readFileSync(fixture);

    const a = await request.post(`${API}/api/v1/documents`, {
      multipart: {
        file: { name: "a.pdf", mimeType: "application/pdf", buffer: bytes },
      },
    });
    const b = await request.post(`${API}/api/v1/documents`, {
      multipart: {
        file: { name: "b.pdf", mimeType: "application/pdf", buffer: bytes },
      },
    });
    expect(a.status()).toBe(201);
    expect(b.status()).toBe(201);
    const jobA = (await a.json()).job_id as string;
    const jobB = (await b.json()).job_id as string;
    const fakeArtifact = "00000000-0000-4000-8000-000000000001";
    const cross = await request.get(`${API}/api/v1/jobs/${jobB}/artifacts/${fakeArtifact}`);
    expect([400, 404]).toContain(cross.status());
    await request.delete(`${API}/api/v1/jobs/${jobA}`);
    await request.delete(`${API}/api/v1/jobs/${jobB}`);
  });
});
